  // answer a question from the passages: the best-matching passage and where it is
  answer(q) {
    const s = ' ' + q.toLowerCase() + ' ', qc = Object.keys(this.concepts).filter(k => this.concepts[k].some(w => s.includes(w)));
    const hits = this.passages.map(p => ({ p, n: p.c.filter(c => qc.includes(c)).length })).filter(x => x.n).sort((a, b) => b.n - a.n);
    return hits.slice(0, 2).map(x => x.p);
  },
